// Phase 3 · Find the customer by email first, then by phone. Decide: create, update or unidentified.
const msg = $('When Executed by Another Workflow').first().json;
const rows = $('Read Customers').all().map(i => i.json).filter(r => r['Customer ID']);
const now = msg.received_at || new Date().toISOString();
const email = msg.customer?.email || null;
const phone = msg.customer?.phone || null;
const digits = p => String(p ?? '').replace(/\D/g, '');
const channelLabel = { web_chat: 'Website Chat', email: 'Email', whatsapp: 'WhatsApp' }[msg.channel] || msg.channel;

let match = null, matched_by = null;
if (email) {
  match = rows.find(r => String(r['Email'] || '').trim().toLowerCase() === email);
  if (match) matched_by = 'email';
}
if (!match && phone) {
  match = rows.find(r => digits(r['Phone']) === phone);
  if (match) matched_by = 'phone';
}

let action, customer;
if (match) {
  // Known customer: keep what we know, fill gaps with anything new, refresh activity
  action = 'update';
  customer = {
    'Customer ID': match['Customer ID'],
    'Name': match['Name'] || msg.customer?.name || '',
    'Email': match['Email'] || email || '',
    'Phone': match['Phone'] ? digits(match['Phone']) : (phone || ''),
    'Company': match['Company'] || msg.customer?.company || '',
    'Preferred Channel': channelLabel,          // last channel used, for now
    'First Interaction': match['First Interaction'] || now,
    'Last Interaction': now,
    'Customer Status': match['Customer Status'] || 'Active',
  };
} else if (email || phone) {
  // New customer: next ID in sequence, e.g. CUST-0001
  action = 'create';
  const maxNum = rows.reduce((m, r) => Math.max(m, parseInt(String(r['Customer ID']).replace(/\D/g, ''), 10) || 0), 0);
  customer = {
    'Customer ID': 'CUST-' + String(maxNum + 1).padStart(4, '0'),
    'Name': msg.customer?.name || '',
    'Email': email || '',
    'Phone': phone || '',
    'Company': msg.customer?.company || '',
    'Preferred Channel': channelLabel,
    'First Interaction': now,
    'Last Interaction': now,
    'Customer Status': 'Active',
  };
} else {
  // No email and no phone: we can't identify them, so no customer record is created
  action = 'unidentified';
  customer = { 'Customer ID': 'UNIDENTIFIED', 'Customer Status': 'Unidentified' };
}

const conversation = {
  'Conversation ID': `${msg.channel}:${msg.thread_id || msg.message_id}`,
  'Customer ID': customer['Customer ID'],
  'Channel': channelLabel,
  'Message ID': msg.message_id,
  'Message': (msg.subject ? `[${msg.subject}] ` : '') + (msg.message_text || ''),
  'Sender Type': 'Customer',
  'Timestamp': now,
  'Intent': '',
  'Response': '',
};

return [{ json: { action, matched_by, customer_row: customer, conversation_row: conversation } }];

// Hand the message back to the channel workflow with the final decision and reply
const msg = $('When Executed by Another Workflow').first().json;
const m = $('Match Customer').first().json;
const decision = $('Holding Reply').isExecuted ? $('Holding Reply').first().json : $('Apply Escalation Rules').first().json;
const ai = decision.ai;
const f = $('Format Reply').first().json;
return [{ json: {
  ...msg,
  customer_id: m.customer_row['Customer ID'],
  customer_status: (ai.human_escalation && m.customer_row['Customer ID'] !== 'UNIDENTIFIED') ? 'Escalated' : m.customer_row['Customer Status'],
  is_new_customer: m.action === 'create',
  matched_by: m.matched_by,
  crm_action: m.action,
  ai: { ...ai, reply: f.final_reply },
  reply_channel: f.channel,
}}];

// Phase 5 · Build the standardized AI input (+ the Tillstone knowledge base): customer ID, channel, message, previous context, customer info
const msg = $('When Executed by Another Workflow').first().json;
const c = $('Match Customer').first().json.customer_row;
const id = c['Customer ID'];

// Previous messages for this customer, from every channel (oldest first, last 10, excluding the new one)
const rows = $('Read Conversations').all().map(i => i.json).filter(r => r['Customer ID']);
const history = id === 'UNIDENTIFIED' ? [] :
  rows.filter(r => r['Customer ID'] === id && r['Message ID'] !== msg.message_id).slice(-10);
const channels = [...new Set(history.map(r => r.Channel))];
const previous_context = history.length
  ? history.map(r => `[${r.Channel} · ${r.Timestamp}] ${r['Sender Type'] || 'Customer'}: ${r.Message}` +
      (r.Response ? `\n[${r.Channel}] Tillstone: ${r.Response}` : '')).join('\n')
  : '(no previous messages)';

const channelLabel = { web_chat: 'Website Chat', email: 'Email', whatsapp: 'WhatsApp' }[msg.channel] || msg.channel;
const ai_input = {
  customer_id: id,
  channel: channelLabel,
  message: (msg.subject ? `[Subject: ${msg.subject}] ` : '') + (msg.message_text || ''),
  previous_context,
  customer: {
    name: c['Name'] || msg.customer?.name || 'Unknown',
    company: c['Company'] || '',
    email: c['Email'] || '',
    phone: c['Phone'] || '',
    status: c['Customer Status'] || '',
    channels_used_before: channels,
  },
};

// Knowledge base: every row of every tab, written as "Column: value" lines
const kbRows = name => $(name).all().map(i => i.json).filter(r => Object.values(r).some(v => String(v ?? '').trim()));
const fmt = r => Object.entries(r).filter(([k, v]) => k !== 'row_number' && String(v ?? '').trim()).map(([k, v]) => `${k}: ${v}`).join(' | ');
const knowledge =
  'PRODUCTS\n' + kbRows('Read KB Products').map(r => '- ' + fmt(r)).join('\n') +
  '\n\nFAQS\n' + kbRows('Read KB FAQs').map(r => `- Q: ${r.Question}\n  A: ${r.Answer}`).join('\n') +
  '\n\nPOLICIES\n' + kbRows('Read KB Policies').map(r => `- ${r.Topic}: ${r.Policy}`).join('\n');

const prompt =
`TILLSTONE KNOWLEDGE BASE
${knowledge}

CUSTOMER
- Customer ID: ${ai_input.customer_id}
- Name: ${ai_input.customer.name}
- Business: ${ai_input.customer.company || 'not given'}
- Status: ${ai_input.customer.status}
- Channels used before: ${channels.length ? channels.join(', ') : 'none'}

CHANNEL OF THIS MESSAGE: ${ai_input.channel}

PREVIOUS CONVERSATION (oldest first):
${previous_context}

NEW MESSAGE:
${ai_input.message}`;

return [{ json: { ai_input, prompt, knowledge_chars: knowledge.length } }];

