// Save the intent and the reply on this message's row in Conversations
const msg = $('When Executed by Another Workflow').first().json;
const decision = $('Holding Reply').isExecuted ? $('Holding Reply').first().json : $('Apply Escalation Rules').first().json;
const ai = decision.ai;
const intent = ai.already_escalated ? 'Escalated: AI paused' : ai.intent + (ai.human_escalation ? ' (escalated)' : '');
return [{ json: { 'Message ID': msg.message_id, 'Intent': intent, 'Response': ai.reply } }];

// Phase 6 · Final formatting per channel (a safety net on top of the AI's style rules)
const msg = $('When Executed by Another Workflow').first().json;
const decision = $('Holding Reply').isExecuted ? $('Holding Reply').first().json : $('Apply Escalation Rules').first().json;
const ai = decision.ai;
const first = String($('Match Customer').first().json.customer_row['Name'] || msg.customer?.name || '').trim().split(/\s+/)[0] || 'Customer';
let text = String(ai.reply || '').trim();
const stripMarkdown = t => t
  .replace(/\*\*(.+?)\*\*/g, '$1').replace(/__(.+?)__/g, '$1')
  .replace(/^#+\s*/gm, '').replace(/^\s*[-*•]\s+/gm, '')
  .replace(/\[(.+?)\]\((.+?)\)/g, '$1 ($2)');

if (!text) text = "Thanks for your message. A member of the Tillstone team will get back to you shortly.";

if (msg.channel === 'web_chat') {
  text = stripMarkdown(text);
} else if (msg.channel === 'whatsapp') {
  text = stripMarkdown(text).replace(/\n{3,}/g, '\n\n');
  if (text.length > 700) text = text.slice(0, 680).replace(/\s+\S*$/, '') + '…';
} else if (msg.channel === 'email') {
  if (!/^dear\b/i.test(text)) text = `Dear ${first},\n\n` + text;
  if (!/best regards/i.test(text)) text = text.replace(/\s+$/, '') + '\n\nBest regards,\nTillstone Support';
}

return [{ json: { channel: msg.channel, final_reply: text } }];

// Phase 8 · Customer is already Escalated: the AI is paused. Send a short holding reply instead.
const c = $('Match Customer').first().json.customer_row;
const first = String(c['Name'] || '').trim().split(/\s+/)[0] || 'there';
const reply = `Hi ${first}, your case is already with our team and a team member will contact you shortly on this channel. Thank you for your patience.`;
return [{ json: { ai: {
  intent: 'Human Assistance', confidence: 1, urgency: 'medium', required_information: [],
  response_type: 'holding_reply', human_escalation: false, already_escalated: true,
  escalation_reason: '', preferred_action: '', important_details: {},
  summary: 'Customer already escalated; AI paused; holding reply sent.',
  conversation_summary: '', reply, answered_from_knowledge_base: false,
}}}];

// Phase 8 · Escalation rules applied on top of the AI's judgement
// v2 (Phase 10 fixes): safety warning when a customer shares an OTP/PIN (#17),
// security advice on fraud escalations (#28), never re-escalate an already
// escalated customer (#23, #29 safety net) (#30 is fixed in the prompt).
const msg = $('When Executed by Another Workflow').first().json;
const c = $('Match Customer').first().json.customer_row;
const id = c['Customer ID'];
const ai = { ...$('AI Understanding').first().json.output };
const first = String(c['Name'] || msg.customer?.name || '').trim().split(/\s+/)[0] || '';
const text = String(msg.message_text || '') + ' ' + String(msg.subject || '');

// Safety net: customer is already with a human → holding reply, no new handoff
if (c['Customer Status'] === 'Escalated') {
  ai.human_escalation = false; ai.already_escalated = true; ai.response_type = 'holding_reply';
  ai.reply = msg.channel === 'email'
    ? `Dear ${first || 'Customer'},\n\nYour case is already with our team and a team member will contact you shortly by email. Thank you for your patience.\n\nBest regards,\nTillstone Support`
    : `Hi ${first || 'there'}, your case is already with our team and a team member will contact you shortly on this channel. Thank you for your patience.`;
  return [{ json: { ai, escalated_by: null } }];
}

let escalated_by = ai.human_escalation ? 'ai' : null;

// Rule 1: these intents always go to a human
if (['Complaint', 'Human Assistance'].includes(ai.intent) && !ai.human_escalation) {
  ai.human_escalation = true; escalated_by = 'rule';
  ai.escalation_reason = ai.escalation_reason || `${ai.intent} always goes to a human`;
}

// Rule 2: repeated unresolved issue = 3rd contact in a row about the same problem
const rows = $('Read Conversations').all().map(i => i.json)
  .filter(r => r['Customer ID'] === id && r['Message ID'] !== msg.message_id);
const recent = id === 'UNIDENTIFIED' ? [] : rows.slice(-4);
const sameTopic = recent.filter(r => r.Intent === ai.intent).length;
if (!ai.human_escalation && sameTopic >= 2 && ['Technical Support', 'Order Information', 'Complaint'].includes(ai.intent)) {
  ai.human_escalation = true; escalated_by = 'rule';
  ai.escalation_reason = `Repeated unresolved issue: contact number ${sameTopic + 1} about ${ai.intent}`;
}

// Safety lines that must survive the fixed handoff template
const sharedSecret = /\b(otp|pin|password|cvv|token)\b/i.test(text) && /\d{4,}/.test(text);
const fraud = /(unauthori[sz]ed|fraud|scam|hack|did not authori[sz]e|didn'?t authori[sz]e|stolen)/i.test(text);
const safety = [
  sharedSecret ? 'For your safety, please never share your OTP, PIN or password with anyone, including Tillstone staff. If you have shared it, change your PIN now.' : '',
  fraud ? 'To protect your account right now, change your PIN and password and do not share any codes with anyone.' : '',
].filter(Boolean).join(' ');

if (ai.human_escalation) {
  ai.response_type = 'escalate_to_human';
  const d = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  ai.escalation_ref = `ESC-${d}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
  const sorry = ai.intent === 'Complaint' ? "I'm sorry about this. " : '';
  const noInfo = ai.answered_from_knowledge_base === false ? "I don't have that information yet. " : '';
  if (id === 'UNIDENTIFIED') {
    // We can't hand over someone we can't contact: ask for contact details instead of promising a call-back
    ai.reply = `${sorry}${noInfo}I'd like to pass this to our team. Please share your phone number or email address so a team member can contact you.${safety ? ' ' + safety : ''}`;
  } else if (msg.channel === 'email') {
    ai.reply = `Dear ${first || 'Customer'},\n\nThank you for contacting Tillstone. ${sorry}${noInfo}I have passed your case to our team (reference ${ai.escalation_ref}). A team member will contact you by email within 4 business hours.${safety ? '\n\n' + safety : ''}\n\nBest regards,\nTillstone Support`;
  } else {
    ai.reply = `${first ? `Thanks, ${first}. ` : ''}${safety ? safety + ' ' : ''}${sorry}${noInfo}I've passed this to our team (reference ${ai.escalation_ref}). A team member will contact you here within 4 business hours.`;
  }
} else if (safety && !/never share/i.test(ai.reply || '')) {
  ai.reply = `${safety} ${ai.reply || ''}`.trim();
}

return [{ json: { ai, escalated_by } }];

// Phase 8 · Handoff summary for the human agent
const msg = $('When Executed by Another Workflow').first().json;
const c = $('Match Customer').first().json.customer_row;
const { ai, escalated_by } = $('Apply Escalation Rules').first().json;
const channelLabel = { web_chat: 'Website Chat', email: 'Email', whatsapp: 'WhatsApp' }[msg.channel] || msg.channel;
const history = $('Read Conversations').all().map(i => i.json)
  .filter(r => r['Customer ID'] === c['Customer ID'] && r['Message ID'] !== msg.message_id).slice(-10);
const channels = [...new Set([...history.map(r => r.Channel), channelLabel])];
const details = Object.entries(ai.important_details || {}).filter(([, v]) => v).map(([k, v]) => `${k}: ${v}`).join(', ') || 'none';

const subject = `[ESCALATION · ${String(ai.urgency).toUpperCase()}] ${c['Name'] || 'Customer'} – ${ai.intent} (${ai.escalation_ref})`;
const body =
`A customer conversation needs a human.

CASE
Reference: ${ai.escalation_ref}
Escalated by: ${escalated_by === 'rule' ? 'business rule' : 'AI'}
Reason: ${ai.escalation_reason || 'n/a'}

CUSTOMER
${c['Customer ID']} · ${c['Name'] || 'Unknown'}${c['Company'] ? ' · ' + c['Company'] : ''}
Email: ${c['Email'] || '-'}   Phone: ${c['Phone'] || '-'}
Channels used: ${channels.join(', ')}
Latest channel: ${channelLabel}

ISSUE
${ai.summary}

CONVERSATION SUMMARY (AI)
${ai.conversation_summary || ai.summary}

AI ANALYSIS
Intent: ${ai.intent} · Urgency: ${ai.urgency} · Confidence: ${ai.confidence}
Customer wants: ${ai.preferred_action || '-'}
Details given: ${details}
Still missing: ${(ai.required_information || []).join(', ') || 'nothing'}

RECENT HISTORY (oldest first)
${history.map(r => `[${r.Channel} · ${r.Timestamp}] Customer: ${r.Message}${r.Response ? `\n   Tillstone: ${r.Response}` : ''}`).join('\n') || '(none)'}
[${channelLabel} · ${msg.received_at}] Customer: ${(msg.subject ? '[' + msg.subject + '] ' : '') + msg.message_text}

WHAT THE CUSTOMER WAS TOLD
${ai.reply}

NEXT STEPS
1. Contact the customer on ${channelLabel} within 4 business hours.
2. The AI is paused for this customer. When resolved, set Customer Status back to "Active" in the Multi-channel AI CRM sheet.`;

return [{ json: { subject, body } }];

// Mark the customer as Escalated in the CRM (this pauses the AI for them)
const c = $('Match Customer').first().json.customer_row;
return [{ json: { 'Customer ID': c['Customer ID'], 'Customer Status': 'Escalated' } }];
